'use strict';
// Local shared-device protection; learning IDs/storage schema stay unchanged.
function installPlayerProtection(){
 const ITERATIONS=600000,MINUTES=5,PROTECTION=KEY+'-protection-v1';
 let authenticated=null,teacher=null,lastActivity=0,busy=false,queue=Promise.resolve(),epoch=0;
 const original={choose:choosePlayer,picker:playerChooser,profile:profileEditor,save,home,start,question:renderQuestion,answer,finish,settings,backup:downloadBackup,preview:previewImport,commit:commitImport,sanitize:sanitizeBackup,navigate};
 const clone=x=>JSON.parse(JSON.stringify(x)),hex=a=>Array.from(new Uint8Array(a),n=>n.toString(16).padStart(2,'0')).join(''),bytes=s=>new Uint8Array(s.match(/../g).map(x=>parseInt(x,16)));
 function fresh(){return {schema:1,revision:0,players:{},rates:{}}}
 function validateSecurity(s){if(!s||s.schema!==1||!Number.isSafeInteger(s.revision)||s.revision<0||!s.players||Array.isArray(s.players)||!s.rates||Array.isArray(s.rates))throw Error('保護設定が不正です。上書きせず停止しました。');const valid=v=>v&&v.algorithm==='PBKDF2-SHA256'&&v.iterations===ITERATIONS&&/^[a-f0-9]{32}$/.test(v.salt)&&/^[a-f0-9]{64}$/.test(v.hash)&&typeof v.version==='string'&&v.version.length<=80;for(const [id,v]of Object.entries(s.players)){if(!/^[a-zA-Z0-9_-]{1,80}$/.test(id)||['__proto__','constructor','prototype'].includes(id)||!valid(v))throw Error('本人用の保護設定が不正です。');}if(!!s.admin!==!!s.recovery||s.admin&&!valid(s.admin)||s.recovery&&!valid(s.recovery))throw Error('先生用の保護設定が不正です。');for(const [id,r]of Object.entries(s.rates)){if(!/^(teacher|recovery|player:[a-zA-Z0-9_-]{1,80})$/.test(id)||!r||!Number.isSafeInteger(r.fails)||r.fails<0||r.fails>100000||!Number.isSafeInteger(r.until)||r.until<0||r.until>1e14)throw Error('誤入力制限が不正です。');}return clone(s)}
 sanitizeBackup=raw=>{const result=original.sanitize(raw);if(raw.security!==undefined)result.security=validateSecurity(raw.security);return result};
 function security(){return state.security?validateSecurity(state.security):fresh()}
 function verifierFor(s,key){return key==='teacher'?s.admin:key==='recovery'?s.recovery:s.players[key.replace(/^player:/,'')]}
 function hasPlayer(id=state.current){try{return id==='guest'?state.current==='guest'&&playerChosen:!!authenticated&&authenticated.id===id&&playerChosen&&security().players[id]?.version===authenticated.version}catch{return false}}
 function isTeacher(){try{return !!teacher&&Date.now()-lastActivity<MINUTES*60000&&security().admin?.version===teacher}catch{return false}}
 function requireTeacher(){if(!isTeacher())throw Error('先生用パスワードで入り直してください。')}
 function requirePlayer(id=state.current){if(!hasPlayer(id)||id==='guest')throw Error('本人のパスワードで入り直してください。')}
 function message(e){toast(e.message||String(e))}
 function storedSecurity(){const mirror=localStorage.getItem(PROTECTION);if(mirror)return validateSecurity(JSON.parse(mirror));const raw=localStorage.getItem(KEY);if(!raw)return fresh();const parsed=JSON.parse(raw);return parsed.security?validateSecurity(parsed.security):fresh()}
 function persist(next){const clean={...next,current:next.current==='guest'?next.players.find(p=>p.id!=='guest')?.id:next.current,players:next.players.filter(p=>p.id!=='guest')};if(!clean.players.length)throw Error('登録済みプレイヤーを1人以上残してください。');const previous=localStorage.getItem(PROTECTION);localStorage.setItem(PROTECTION,JSON.stringify(next.security));try{localStorage.setItem(KEY,JSON.stringify(clean))}catch(error){try{if(previous===null)localStorage.removeItem(PROTECTION);else localStorage.setItem(PROTECTION,previous)}catch{}throw error}state=next;return next}
 async function transaction(fn){const run=async()=>{const task=async()=>{const expected=security().revision;if(storedSecurity().revision!==expected)throw Error('別の画面で保護設定が変わりました。開き直してください。');const next=clone(state);next.security=security();await fn(next);if(storedSecurity().revision!==expected)throw Error('別の画面で設定が変わりました。やり直してください。');next.security.revision++;validateSecurity(next.security);try{return persist(next)}catch(e){throw Error('保存できませんでした。変更前の記録と保護設定を保持しています。空き容量を確認してください。')}};return navigator.locks? navigator.locks.request(KEY+'-security',task):task()};const p=queue.then(run,run);queue=p.catch(()=>{});return p}
 async function derive(password,salt){if(!globalThis.crypto?.subtle)throw Error('安全なパスワード処理が使えません。HTTPS対応ブラウザで開いてください。');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return hex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:bytes(salt),iterations:ITERATIONS,hash:'SHA-256'},key,256))}
 async function verifier(password){const salt=hex(crypto.getRandomValues(new Uint8Array(16)));return {algorithm:'PBKDF2-SHA256',iterations:ITERATIONS,salt,hash:await derive(password,salt),version:crypto.randomUUID()}}
 async function check(key,password){const s=security(),v=verifierFor(s,key),r=s.rates[key]||{fails:0,until:0};if(r.until>Date.now())throw Error('あと'+Math.ceil((r.until-Date.now())/1000)+'秒待ってください。');if(!v)throw Error('先生に最初のパスワードを設定してもらってください。');const got=await derive(password,v.salt);let diff=0;for(let i=0;i<got.length;i++)diff|=got.charCodeAt(i)^v.hash.charCodeAt(i);await transaction(next=>{if(verifierFor(next.security,key)?.version!==v.version)throw Error('設定が変わりました。やり直してください。');const currentRate=next.security.rates[key]||{fails:0,until:0};if(currentRate.until>Date.now())throw Error('あと'+Math.ceil((currentRate.until-Date.now())/1000)+'秒待ってください。');if(diff){const n=currentRate.fails+1;next.security.rates[key]={fails:n,until:n>=5?Date.now()+Math.min(900000,30000*2**Math.floor((n-5)/5)):0}}else delete next.security.rates[key]});if(diff)throw Error(r.fails+1>=5?'パスワードが違います。しばらく待ってから再入力してください。':'パスワードが違います。');return v.version}
 function passwordFields(id,label,min=4,again=false){return `<label for="${id}">${label}${again?`（${min}〜128文字）`:''}</label><div class="passwordRow"><input id="${id}" type="password" required maxlength="128" ${again?`minlength="${min}" maxlength="128"`:''} autocomplete="${again?'new-password':'current-password'}"><button type="button" data-show="${id}" aria-label="${label}を表示" aria-pressed="false">表示</button></div>${again?`<label for="${id}Again">確認のためもう一度</label><input id="${id}Again" type="password" required autocomplete="new-password" maxlength="128">`:''}`}
 function newPassword(id,min=4){const value=$('#'+id).value;if(value.length<min||value.length>128||!value.trim())throw Error(min+'〜128文字で設定してください。');if(value!==$('#'+id+'Again').value)throw Error('確認用パスワードが一致しません。');return value}
 function runForm(id,fn){const form=$('#'+id),ticket=epoch;document.querySelectorAll('[data-show]').forEach(b=>b.onclick=()=>{const input=$('#'+b.dataset.show),show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'隠す':'表示';b.setAttribute('aria-pressed',String(show));if($('#'+b.dataset.show+'Again'))$('#'+b.dataset.show+'Again').type=input.type});form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const b=form.querySelector('[type=submit]');b.disabled=true;form.querySelector('[role=status]').textContent='確認・保存しています…';const guard=()=>{if(ticket!==epoch||!form.isConnected)throw Error('画面が変わりました。もう一度操作してください。')};try{await fn(guard)}catch(e){const out=form.querySelector('[role=status]');if(out?.isConnected)out.textContent=e.message;else message(e)}finally{busy=false;if(b.isConnected)b.disabled=false}}}
 const iconPicker=p=>Object.entries(iconGroups).map(([name,list])=>`<details ${list.includes(p?.icon||'🌱')?'open':''}><summary>${name}</summary><div class="iconPicker">${list.map(i=>`<button type="button" data-sec-icon="${esc(i)}" aria-pressed="${i===(p?.icon||'🌱')}" class="${i===(p?.icon||'🌱')?'selected':''}">${i}</button>`).join('')}</div></details>`).join('');
 function bindIcons(p){let icon=p?.icon||'🌱';document.querySelectorAll('[data-sec-icon]').forEach(b=>b.onclick=()=>{icon=b.dataset.secIcon;document.querySelectorAll('[data-sec-icon]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))})});return ()=>icon}
 function setupNeeded(){toast('共用端末を渡す前に「先生の管理」で初期設定してください。')}
 function login(id){const p=state.players.find(p=>p.id===id);if(!p)return;authenticated=null;playerChosen=false;teacher=null;epoch++;if(!security().players[id]){setupNeeded();return}modal(`<h2>パスワードを入力</h2><p>${esc(p.icon)} ${esc(p.name)}</p><form id="playerLogin">${passwordFields('loginPassword','本人用パスワード')}<button type="submit" class="primary wide">このプレイヤーで遊ぶ</button><p role="status" aria-live="polite"></p></form><p class="note">忘れたときは先生に再設定してもらってください。</p>`);runForm('playerLogin',async guard=>{const version=await check('player:'+id,$('#loginPassword').value);guard();authenticated={id,version};playerChosen=true;state.current=id;save();$('#modal').close();navigate(home);if(hasNameEmoji(p.name))toast('名前に絵文字が含まれています。プロフィールから名前を変更してください。')})}
 choosePlayer=id=>{try{if(id==='guest'){authenticated=null;teacher=null;epoch++;return original.choose(id)}login(id)}catch(e){message(e)}};
 playerChooser=()=>{try{const mirror=localStorage.getItem(PROTECTION);if(mirror)state.security=validateSecurity(JSON.parse(mirror));else security()}catch(error){playerChosen=false;authenticated=null;teacher=null;view='players';app.innerHTML='<div class="card"><h1>保護設定を読み込めません</h1><p>上書きせず停止しました。記録を削除せず先生に相談してください。</p></div>';return}authenticated=null;teacher=null;playerChosen=false;epoch++;original.picker();$('#app .setup').querySelector('.card')?.remove();const grid=$('.playerGrid');grid.insertAdjacentHTML('afterend','<div class="row section"><button id="secureNewPlayer">新しいプレイヤー</button><button id="secureGuest">ゲストで遊ぶ</button><button id="teacherEntry">先生の管理</button></div><p class="note">自分の名前を選び、パスワードで入ってください。未設定の人は先生に設定してもらいます。初回は先生が共用端末を渡す前に管理設定をしてください。</p><p class="note">端末内で日常のいたずらを防ぐ保護です。保存データの直接改変は防げません。古いタブを閉じてから共用してください。</p>');$('#secureNewPlayer').onclick=()=>profileForm(null);$('#secureGuest').onclick=()=>{state.players=state.players.filter(p=>p.id!=='guest');state.players.push({id:'guest',name:'ゲスト',icon:'🍃',records:{},sessions:[],resume:null});choosePlayer('guest')};$('#teacherEntry').onclick=teacherEntry};
 players=()=>{if(busy)return;navigate(playerChooser)};
 function profileForm(id,admin=false,afterSave){try{if(admin)requireTeacher();else if(id)requirePlayer(id);if(!security().admin){setupNeeded();return}const p=id?state.players.find(x=>x.id===id):null;if(id&&!p)throw Error('プレイヤーがありません。');modal(`<h2>${p?'プロフィールを変更':'新しいプレイヤー'}</h2><form id="secureProfile"><label for="profileName">ニックネーム（20文字まで・絵文字なし）</label><input id="profileName" maxlength="20" required value="${esc(p?.name||'')}" autocomplete="nickname">${iconPicker(p)}${p&&!admin?passwordFields('profilePassword','現在の本人用パスワード'):!p?passwordFields('newPassword','本人用パスワード',4,true):''}${p&&!admin?`<label for="profileTitle">称号</label><select id="profileTitle"><option value="">地図の旅人</option>${milestones(p).filter(b=>b.unlocked).map(b=>`<option value="${b.id}">${b.name}</option>`).join('')}</select>`:''}<button type="submit" id="profileSave" class="primary wide">保存する</button><p role="status"></p></form>${p&&!admin?'<button id="changeOwnPassword">本人用パスワードを変更</button>':''}`);const selected=bindIcons(p);if($('#profileTitle'))$('#profileTitle').value=p.titleCode||'';$('#changeOwnPassword')?.addEventListener('click',()=>passwordForm(id));runForm('secureProfile',async guard=>{const name=$('#profileName').value.trim(),icon=selected(),title=$('#profileTitle')?.value;if(!validName(name))throw Error('名前の入力を確認してください。');let v;if(p&&!admin)await check('player:'+id,$('#profilePassword').value);if(!p)v=await verifier(newPassword('newPassword'));guard();if(admin)requireTeacher();else if(p)requirePlayer(id);const newId=id||'u'+Date.now()+'-'+crypto.randomUUID().slice(0,8);await transaction(next=>{guard();if(admin)requireTeacher();else if(p)requirePlayer(id);const target=next.players.find(x=>x.id===id);if(p){if(!target)throw Error('プレイヤーがありません。');target.name=name;target.icon=icon;if(title!==undefined)target.titleCode=milestones(target).some(b=>b.unlocked&&b.id===title)?title:''}else{if(next.players.filter(x=>x.id!=='guest').length>=100)throw Error('登録上限は100人です。');next.players.push({id:newId,name,icon,titleCode:'',records:{},sessions:[],resume:null});next.security.players[newId]=v}});$('#modal').close();if(admin)teacherPanel();else if(p){if(typeof afterSave==='function')afterSave();else navigate(home)}else navigate(playerChooser)})}catch(e){message(e)}}
 profileEditor=afterSave=>{if(state.current==='guest'){toast('ゲストはプロフィールを保存できません。');return}profileForm(state.current,false,afterSave)};
 function passwordForm(id,admin=false){try{if(admin)requireTeacher();else requirePlayer(id);const p=state.players.find(x=>x.id===id);modal(`<h2>${admin?'本人用パスワードを設定・再設定':'本人用パスワードを変更'}</h2><p>${esc(p?.name)}</p><form id="changePassword">${admin?'':passwordFields('oldPassword','現在の本人用パスワード')}${passwordFields('nextPassword','新しい本人用パスワード',4,true)}<button type="submit" class="primary">保存する</button><p role="status"></p></form>`);runForm('changePassword',async guard=>{if(!admin)await check('player:'+id,$('#oldPassword').value);const v=await verifier(newPassword('nextPassword'));guard();await transaction(next=>{guard();if(admin)requireTeacher();else requirePlayer(id);if(!next.players.some(p=>p.id===id))throw Error('プレイヤーがありません。');next.security.players[id]=v;delete next.security.rates['player:'+id]});if(!admin)authenticated={id,version:v.version};$('#modal').close();if(admin)teacherPanel();else navigate(home)})}catch(e){message(e)}}
 function teacherEntry(){try{if(!security().admin)return setupTeacher();authenticated=null;playerChosen=false;epoch++;modal(`<h2>先生の管理</h2><form id="teacherLogin">${passwordFields('teacherPassword','先生用パスワード')}<button type="submit" class="primary">管理画面へ</button><p role="status"></p></form><button id="recoverTeacher">先生用パスワードを忘れた場合</button>`);$('#recoverTeacher').onclick=()=>teacherPasswordForm(true);runForm('teacherLogin',async guard=>{const v=await check('teacher',$('#teacherPassword').value);guard();$('#modal').close();teacher=v;lastActivity=Date.now();original.navigate(teacherPanel)})}catch(e){message(e)}}
 function recoveryDisplay(code){modal(`<h2>復旧コードを保管してください</h2><p>この画面で一度だけ表示します。先生用パスワードを忘れた場合に使います。子どもに見せず、端末の外へ控えてください。</p><p class="recoveryCode" id="recoveryCode">${code}</p><p class="note">先生用パスワードと復旧コードを両方失うと、共通の解除パスワードはありません。記録を消して解除する案内は行いません。</p><button id="recoveryDone" class="primary">コードを保管しました</button>`);$('#recoveryDone').onclick=()=>{$('#modal').close();teacherPanel()}}
 function setupTeacher(){modal(`<h2>先生用の初期設定</h2><p>先生が児童へ端末を渡す前に設定してください。端末内の仕組みでは、最初に設定する人が先生かどうかを判別できません。</p><p class="note">ほかの古いタブを閉じてください。既存のプレイヤーIDと記録は残します。</p><form id="teacherSetup">${passwordFields('setupPassword','先生用パスワード',6,true)}<label><input type="checkbox" id="teacherConsent" required>先生として設定し、復旧コードを端末の外で保管します</label><button type="submit" class="primary">初期設定する</button><p role="status"></p></form>`);runForm('teacherSetup',async guard=>{if(!$('#teacherConsent').checked)throw Error('確認欄を選んでください。');const admin=await verifier(newPassword('setupPassword',6)),code=hex(crypto.getRandomValues(new Uint8Array(16))),recovery=await verifier(code);guard();await transaction(next=>{guard();if(next.security.admin)throw Error('すでに設定済みです。先生用パスワードで入ってください。');next.security.admin=admin;next.security.recovery=recovery});$('#modal').close();authenticated=null;playerChosen=false;teacher=admin.version;lastActivity=Date.now();original.navigate(teacherPanel);recoveryDisplay(code)})}
 function rotateRecovery(){try{requireTeacher();modal(`<h2>復旧コードを再発行</h2><p>以前の復旧コードは使えなくなります。新しいコードを端末の外で保管してください。</p><form id="rotateRecovery">${passwordFields('rotatePassword','現在の先生用パスワード')}<button type="submit" class="primary">再発行する</button><p role="status"></p></form>`);runForm('rotateRecovery',async guard=>{const version=await check('teacher',$('#rotatePassword').value),code=hex(crypto.getRandomValues(new Uint8Array(16))),recovery=await verifier(code);guard();await transaction(next=>{guard();requireTeacher();if(next.security.admin.version!==version)throw Error('設定が変わりました。');next.security.recovery=recovery;delete next.security.rates.recovery});$('#modal').close();teacherPanel();recoveryDisplay(code)})}catch(e){message(e)}}
 function teacherPasswordForm(recover=false){try{if(!recover)requireTeacher();modal(`<h2>${recover?'先生用パスワードの復旧':'先生用パスワードを変更'}</h2><form id="teacherChange">${passwordFields('teacherOld',recover?'保管した復旧コード':'現在の先生用パスワード')}${passwordFields('teacherNext','新しい先生用パスワード',6,true)}<button type="submit" class="primary">再設定する</button><p role="status"></p></form><p class="note">復旧コードにも誤入力制限があります。復旧後は新しいコードを発行し、以前のコードは使えなくなります。</p>`);runForm('teacherChange',async guard=>{const key=recover?'recovery':'teacher',version=await check(key,$('#teacherOld').value),admin=await verifier(newPassword('teacherNext',6));let code,recovery;if(recover){code=hex(crypto.getRandomValues(new Uint8Array(16)));recovery=await verifier(code)}guard();await transaction(next=>{guard();if(!recover)requireTeacher();if(verifierFor(next.security,key)?.version!==version)throw Error('設定が変わりました。');next.security.admin=admin;if(recover){next.security.recovery=recovery;delete next.security.rates.teacher}});$('#modal').close();teacher=admin.version;lastActivity=Date.now();authenticated=null;playerChosen=false;original.navigate(teacherPanel);if(code)recoveryDisplay(code)})}catch(e){message(e)}}
 function destructive(id,action){try{requireTeacher();const p=state.players.find(x=>x.id===id);if(!p)return;modal(`<h2>「${esc(p.name)}」${action==='delete'?'を削除':'の学習記録を初期化'}しますか？</h2><p>対象はこの人の学習記録・ランキング履歴・勲章・称号・途中保存です。他のプレイヤーには影響しません。先にバックアップを保管できます。</p><form id="teacherDestructive"><label><input type="checkbox" id="deleteConsent" required>対象者と影響範囲を確認しました</label><button type="submit" class="primary">確認して実行する</button><p role="status"></p></form>`);runForm('teacherDestructive',async guard=>{if(!$('#deleteConsent').checked)throw Error('確認欄を選んでください。');await transaction(next=>{guard();requireTeacher();if(action==='delete'){if(next.players.filter(x=>x.id!=='guest').length<=1)throw Error('最後の1人は削除できません。別のプレイヤーを追加してから操作してください。');next.players=next.players.filter(x=>x.id!==id);delete next.security.players[id];delete next.security.rates['player:'+id];if(next.current===id)next.current=next.players.find(x=>x.id!=='guest').id}else{const p=next.players.find(x=>x.id===id);if(!p)throw Error('プレイヤーがありません。');p.records={};p.sessions=[];p.resume=null;p.titleCode=''}});$('#modal').close();teacherPanel()})}catch(e){message(e)}}
 function teacherPanel(){requireTeacher();view='teacher';game=null;app.innerHTML=`<div class="setup"><div class="row between"><h1>先生の管理</h1><button id="teacherLogout">管理を終了</button></div><p class="note">本人用パスワードが未設定の人には、ここから設定してください。5分間操作しないと管理を終了します。</p><label for="teacherSearch">名前で探す</label><input id="teacherSearch" type="search"><div id="teacherRows"></div><div class="row section"><button id="teacherAdd">プレイヤーを追加</button><button id="teacherExport">全員のバックアップ</button><button id="teacherChange">先生用パスワードを変更</button><button id="teacherRecoveryRotate">復旧コードを再発行</button></div><label for="teacherImport">バックアップを読み込む（全員分を置き換え）</label><input id="teacherImport" type="file" accept=".json,application/json"><button id="teacherUndo" ${readSaved(RECOVERY_KEY)?'':'disabled'}>最後の読み込み前へ戻す</button><p class="note">認証の検証情報を含めて書き出します。古いバックアップを読み込んでも、現在の先生の保護を解除しません。同じIDの本人用保護は現在のものを優先し、新規IDはバックアップの保護を引き継ぐか先生が設定します。</p></div>`;const draw=()=>{$('#teacherRows').innerHTML=state.players.filter(p=>p.id!=='guest'&&norm(p.name).includes(norm($('#teacherSearch').value))).map(p=>`<section class="card section teacherPlayer"><b>${esc(p.icon)} ${esc(p.name)}</b><p class="note">${security().players[p.id]?'パスワード設定済み':'パスワード未設定'} ／ ${Object.values(p.records).reduce((n,r)=>n+r.attempts,0)}回答 ／ ${Object.values(p.records).reduce((n,r)=>n+r.correct,0)}正解</p><div class="row"><button data-admin="password" data-id="${p.id}">パスワード設定・再設定</button><button data-admin="profile" data-id="${p.id}">名前・アイコン</button><button data-admin="reset" data-id="${p.id}">学習記録を初期化</button><button data-admin="delete" data-id="${p.id}">プレイヤーを削除</button></div></section>`).join('')};draw();$('#teacherSearch').oninput=draw;$('#teacherRows').onclick=e=>{const b=e.target.closest('[data-admin]');if(!b)return;try{requireTeacher();const id=b.dataset.id;if(b.dataset.admin==='password')passwordForm(id,true);else if(b.dataset.admin==='profile')profileForm(id,true);else destructive(id,b.dataset.admin)}catch(e){message(e)}};$('#teacherLogout').onclick=()=>navigate(playerChooser);$('#teacherAdd').onclick=()=>profileForm(null,true);$('#teacherExport').onclick=()=>{try{downloadBackup()}catch(e){message(e)}};$('#teacherChange').onclick=()=>teacherPasswordForm();$('#teacherRecoveryRotate').onclick=rotateRecovery;$('#teacherImport').onchange=e=>previewImport(e.target.files[0]);$('#teacherUndo').onclick=()=>{try{requireTeacher();const before=sanitizeBackup(JSON.parse(readSaved(RECOVERY_KEY)));modal('<h2>読み込み前の全員の記録へ戻しますか？</h2><p>現在の全プレイヤーの記録を置き換えます。現在の先生用保護と、同じIDの本人用保護を維持します。</p><button id="teacherUndoConfirm">確認して戻す</button>');$('#teacherUndoConfirm').onclick=()=>{try{commitImport(before);$('#modal').close();navigate(playerChooser)}catch(e){message(e)}}}catch(e){message(e)}}}
 navigate=fn=>{epoch++;original.navigate(fn);if(view!=='teacher')teacher=null};
 home=()=>{if(!hasPlayer())return playerChooser();return original.home()};
 start=o=>{if(!hasPlayer()){navigate(playerChooser);return}return original.start(o)};
 renderQuestion=()=>{if(!hasPlayer())return playerChooser();return original.question()};
 answer=(...args)=>{if(!hasPlayer())return;return original.answer(...args)};
 finish=()=>{if(!hasPlayer())return;return original.finish()};
 save=()=>{if(!hasPlayer()&&!isTeacher())return false;try{if(storedSecurity().revision!==security().revision)throw Error('保護設定が変わりました。開き直してください。');original.save();return true}catch(e){message(e);return false}};
 downloadBackup=()=>{requireTeacher();return original.backup()};
 previewImport=async file=>{try{requireTeacher();await original.preview(file);if($('#confirmImport'))$('#modalBody').insertAdjacentHTML('beforeend','<p class="note">現在の先生用保護を維持します。同じIDの本人用保護は現在の設定を優先します。新規IDが未設定の場合は先生がパスワードを設定してください。</p>')}catch(e){message(e)}};
 commitImport=next=>{requireTeacher();const current=security(),incoming=next.security?validateSecurity(next.security):fresh(),merged={...current,players:{},revision:current.revision+1};for(const p of next.players){const v=current.players[p.id]||incoming.players[p.id];if(v)merged.players[p.id]=v;}const safe={...next,security:merged};if(storedSecurity().revision!==current.revision)throw Error('別の画面で設定が変わりました。');const previousRecovery=localStorage.getItem(RECOVERY_KEY);try{localStorage.setItem(RECOVERY_KEY,JSON.stringify({...state,players:state.players.filter(p=>p.id!=='guest')}));persist(safe)}catch(error){try{if(previousRecovery===null)localStorage.removeItem(RECOVERY_KEY);else localStorage.setItem(RECOVERY_KEY,previousRecovery)}catch{}throw Error('読み込みに失敗しました。現在の記録と保護を保持しています。')}authenticated=null;playerChosen=false;teacher=null;epoch++};
 settings=()=>{if(!hasPlayer())return playerChooser();original.settings();const section=$('#export')?.closest('section');if(section)section.innerHTML='<h2>記録の管理</h2><p class="note">全員のバックアップ・読み込み・削除・初期化は先生の管理から行います。</p><button id="settingsTeacher">先生の管理</button>';$('#settingsTeacher').onclick=teacherEntry};
 document.addEventListener('click',e=>{if(busy&&!e.target.closest('#modal form')){e.preventDefault();e.stopImmediatePropagation()}},true);
 $('#modal').addEventListener('cancel',e=>{if(busy)e.preventDefault()});$('#modal').addEventListener('close',()=>{if(!$('#modal').open){if($('#recoveryCode'))$('#modalBody').replaceChildren();else $('#modal').querySelectorAll('input[type=password]').forEach(input=>input.value='');if(!busy)epoch++}});
 ['pointerdown','keydown','input'].forEach(type=>document.addEventListener(type,()=>{if(isTeacher())lastActivity=Date.now()},true));
 setInterval(()=>{if(teacher&&!isTeacher()){teacher=null;authenticated=null;playerChosen=false;epoch++;$('#modal').close();original.navigate(playerChooser);toast('先生の管理を終了しました。')}} ,1000);
 window.addEventListener('pagehide',()=>{teacher=null;authenticated=null;playerChosen=false;epoch++;$('#modal').close();$('#modalBody').replaceChildren()});
 window.addEventListener('pageshow',e=>{if(e.persisted){$('#modal').close();$('#modalBody').replaceChildren();original.navigate(playerChooser)}});
 document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&teacher){teacher=null;epoch++;$('#modal').close();original.navigate(playerChooser)}});
 window.addEventListener('storage',e=>{if(e.key!==KEY)return;authenticated=null;teacher=null;playerChosen=false;epoch++;try{state=sanitizeBackup(JSON.parse(e.newValue));const mirror=localStorage.getItem(PROTECTION);if(mirror)state.security=validateSecurity(JSON.parse(mirror));$('#modal').close();original.navigate(playerChooser);toast('別の画面で記録が更新されたため、選択画面へ戻りました。')}catch(err){app.innerHTML='<h1>記録を保護しています</h1><p>別画面の保存内容を読み込めません。記録を削除せず、先生に相談してください。</p>'}});
}
